def resolve_tool(
    tool_spec: ToolSpec, conv_state: "ConversationState"
) -> Sequence[Tool]:
    with _LOCK:
        resolver = _REG.get(tool_spec.name)

    if resolver is None:
        raise KeyError(f"Tool '{tool_spec.name}' is not registered")

    return resolver(tool_spec.params, conv_state)

